{"code":""""Summarize adjacent integer windows."""

def solve(values, width):
    """Return all intended contiguous window sums."""
    if width <= 0 or width > len(values):
        return []
    return [sum(values[index:index + width]) for index in range(len(values) - width + 1)]"}

